"use client";

import { useState, useEffect } from "react";
import Link from "next/link";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";
import {
  Plus,
  Eye,
  Pencil,
  Trash2,
  Search,
  UserCircle,
  Loader2,
} from "lucide-react";
import { getUsers, deleteUser, type User } from "@/lib/api/user";
import { useToast } from "@/hooks/use-toast";
import { useUser } from "@/context/UserContext";

export default function UserListPage() {
  const [page, setPage] = useState(1);
  const [limit] = useState(10);
  const [pagination, setPagination] = useState<{
    totalPages: number;
    totalCount: number;
    hasNextPage: boolean;
    hasPrevPage: boolean;
  } | null>(null);
  const [users, setUsers] = useState<User[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [loading, setLoading] = useState(true);
  const [deleting, setDeleting] = useState<string | null>(null);
  const { toast } = useToast();
  const { user: currentUser } = useUser();

  useEffect(() => {
    setPage(1);
  }, [searchTerm]);

  useEffect(() => {
    fetchUsers();
  }, [page]);

  const fetchUsers = async () => {
    setLoading(true);
    try {
      const response = await getUsers({
        page,
        limit,
        search: searchTerm || undefined,
      });

      if (response.success && response.users) {
        setUsers(response.users);
        setPagination(response.pagination ?? null);
      } else {
        toast({
          title: "Error",
          description: response.error || "Failed to fetch users",
          variant: "destructive",
        });
      }
    } catch {
      toast({
        title: "Error",
        description: "Failed to fetch users",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id: string, userName: string) => {
    setDeleting(id);
    try {
      const response = await deleteUser(id);
      if (response.success) {
        setUsers(users.filter((user) => user.id !== id));
        toast({
          title: "Success",
          description: `User "${userName}" deleted successfully`,
        });
      } else {
        toast({
          title: "Error",
          description: response.error || "Failed to delete user",
          variant: "destructive",
        });
      }
    } catch {
      toast({
        title: "Error",
        description: "Failed to delete user",
        variant: "destructive",
      });
    } finally {
      setDeleting(null);
    }
  };

  return (
    <div className="p-4 md:p-6 lg:p-8">
      <div className="mx-auto max-w-7xl">
        {/* Header */}
        <div className="mb-6 flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
          <div>
            <h1 className="text-2xl font-bold text-white md:text-3xl">
              User Management
            </h1>
            <p className="mt-1 text-sm text-gray-400">
              Manage all registered users and their permissions
            </p>
          </div>

          {currentUser?.role === "ADMIN" ? (
            <Link href="/users/add">
              <Button className="gap-2 bg-[#8B0000] text-white hover:bg-[#6B0000]">
                <Plus className="h-4 w-4" />
                Add New User
              </Button>
            </Link>
          ) : null}
        </div>

        {/* Search */}
        <div className="mb-6 flex flex-col gap-4 sm:flex-row sm:items-center">
          <div className="relative flex-1 sm:max-w-xs">
            <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-gray-500" />
            <Input
              placeholder="Search users..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter") {
                  e.preventDefault();
                  setPage(1);
                  fetchUsers();
                }
              }}
              className="border-[#333] bg-[#222] pl-10 text-white placeholder:text-gray-500 focus:border-[#8B0000] focus:ring-[#8B0000]"
            />
          </div>
          <p className="text-sm text-gray-400">
            Showing {users.length} of {pagination?.totalCount ?? 0} users
          </p>
        </div>

        {/* Loading State */}
        {loading && (
          <div className="flex flex-col items-center justify-center rounded-lg border border-[#333] bg-[#222] py-12">
            <Loader2 className="mb-4 h-12 w-12 animate-spin text-[#8B0000]" />
            <p className="text-lg font-medium text-gray-400">
              Loading users...
            </p>
          </div>
        )}

        {/* Table - Desktop */}
        {!loading && (
          <div className="hidden rounded-lg border border-[#333] bg-[#222] md:block">
            <Table>
              <TableHeader>
                <TableRow className="border-[#333] hover:bg-transparent">
                  <TableHead className="text-gray-400">Name</TableHead>
                  <TableHead className="text-gray-400">Email</TableHead>
                  <TableHead className="text-gray-400">Role</TableHead>
                  <TableHead className="text-gray-400">Status</TableHead>
                  <TableHead className="text-gray-400">Created</TableHead>
                  <TableHead className="text-right text-gray-400">
                    Actions
                  </TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {users.map((user) => (
                  <TableRow
                    key={user.id}
                    className="border-[#333] hover:bg-[#2a2a2a]"
                  >
                    <TableCell className="font-medium text-white">
                      {user.name}
                    </TableCell>
                    <TableCell className="text-gray-300">
                      {user.email}
                    </TableCell>
                    <TableCell>
                      <Badge
                        className={
                          user?.role === "ADMIN"
                            ? "bg-yellow-400 text-black font-medium"
                            : user?.role === "OPERATOR"
                              ? "bg-blue-600/20 text-blue-400 hover:bg-blue-600/30"
                              : "bg-gray-600/20 text-gray-300 hover:bg-gray-600/30"
                        }
                      >
                        {user?.role}
                      </Badge>
                    </TableCell>
                    <TableCell>
                      <Badge
                        className={
                          user.isActive
                            ? "bg-green-600/20 text-green-400 hover:bg-green-600/30"
                            : "bg-red-600/20 text-red-400 hover:bg-red-600/30"
                        }
                      >
                        {user.isActive ? "Active" : "Inactive"}
                      </Badge>
                    </TableCell>
                    <TableCell className="text-sm text-gray-400">
                      {new Date(user.createdAt).toLocaleDateString()}
                    </TableCell>
                    <TableCell className="text-right">
                      <div className="flex items-center justify-end gap-2">
                        <Link href={`/users/${user.id}`}>
                          <Button
                            variant="ghost"
                            size="icon"
                            className="h-8 w-8 text-gray-400 hover:bg-[#333] hover:text-white"
                          >
                            <Eye className="h-4 w-4" />
                          </Button>
                        </Link>

                        {currentUser?.role === "ADMIN" ? (
                          <Link href={`/users/${user.id}/edit`}>
                            <Button
                              variant="ghost"
                              size="icon"
                              className="h-8 w-8 text-gray-400 hover:bg-[#333] hover:text-white"
                            >
                              <Pencil className="h-4 w-4" />
                            </Button>
                          </Link>
                        ) : null}
                        {currentUser?.role === "ADMIN" ? (
                          <AlertDialog>
                            <AlertDialogTrigger asChild>
                              <Button
                                variant="ghost"
                                size="icon"
                                className="h-8 w-8 text-gray-400 hover:bg-red-600/20 hover:text-red-400"
                                disabled={deleting === user.id}
                              >
                                {deleting === user.id ? (
                                  <Loader2 className="h-4 w-4 animate-spin" />
                                ) : (
                                  <Trash2 className="h-4 w-4" />
                                )}
                              </Button>
                            </AlertDialogTrigger>
                            <AlertDialogContent className="border-[#333] bg-[#222]">
                              <AlertDialogHeader>
                                <AlertDialogTitle className="text-white">
                                  Delete User
                                </AlertDialogTitle>
                                <AlertDialogDescription className="text-gray-400">
                                  Are you sure you want to delete "{user.name}
                                  "? This action cannot be undone.
                                </AlertDialogDescription>
                              </AlertDialogHeader>
                              <AlertDialogFooter>
                                <AlertDialogCancel className="border-[#333] bg-transparent text-white hover:bg-[#333]">
                                  Cancel
                                </AlertDialogCancel>
                                <AlertDialogAction
                                  onClick={() =>
                                    handleDelete(user.id, user.name)
                                  }
                                  className="bg-red-600 text-white hover:bg-red-700"
                                >
                                  Delete
                                </AlertDialogAction>
                              </AlertDialogFooter>
                            </AlertDialogContent>
                          </AlertDialog>
                        ) : null}
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>
        )}

        {/* Cards - Mobile */}
        {!loading && (
          <div className="flex flex-col gap-4 md:hidden">
            {users.map((user) => (
              <div
                key={user.id}
                className="rounded-lg border border-[#333] bg-[#222] p-4"
              >
                <div className="mb-3 flex items-start justify-between">
                  <div>
                    <p className="text-xs text-gray-500">{user.email}</p>
                    <h3 className="font-medium text-white">{user.name}</h3>
                  </div>
                  <Badge
                    className={
                      String(user.status).toLowerCase() === "active"
                        ? "bg-green-600/20 text-green-400"
                        : "bg-red-600/20 text-red-400"
                    }
                  >
                    {String(user.status).toLowerCase() === "active"
                      ? "Active"
                      : "Inactive"}
                  </Badge>
                </div>
                <div className="mb-4 flex items-center gap-2 text-sm text-gray-400">
                  <UserCircle className="h-4 w-4" />
                  <span>{user?.role}</span>
                </div>
                <div className="flex gap-2">
                  <Link href={`/users/${user.id}`} className="flex-1">
                    <Button
                      variant="outline"
                      size="sm"
                      className="w-full gap-2 border-[#333] bg-transparent text-white hover:bg-[#333]"
                    >
                      <Eye className="h-4 w-4" />
                      View
                    </Button>
                  </Link>
                  {currentUser?.role === "ADMIN" ? (
                    <Link href={`/users/${user.id}/edit`} className="flex-1">
                      <Button
                        variant="outline"
                        size="sm"
                        className="w-full gap-2 border-[#333] bg-transparent text-white hover:bg-[#333]"
                      >
                        <Pencil className="h-4 w-4" />
                        Edit
                      </Button>
                    </Link>
                  ) : null}
                  {currentUser?.role === "ADMIN" ? (
                    <AlertDialog>
                      <AlertDialogTrigger asChild>
                        <Button
                          variant="outline"
                          size="sm"
                          className="gap-2 border-[#333] bg-transparent text-red-400 hover:bg-red-600/20"
                          disabled={deleting === user.id}
                        >
                          {deleting === user.id ? (
                            <Loader2 className="h-4 w-4 animate-spin" />
                          ) : (
                            <Trash2 className="h-4 w-4" />
                          )}
                        </Button>
                      </AlertDialogTrigger>
                      <AlertDialogContent className="border-[#333] bg-[#222]">
                        <AlertDialogHeader>
                          <AlertDialogTitle className="text-white">
                            Delete User
                          </AlertDialogTitle>
                          <AlertDialogDescription className="text-gray-400">
                            Are you sure you want to delete "{user.name}"? This
                            action cannot be undone.
                          </AlertDialogDescription>
                        </AlertDialogHeader>
                        <AlertDialogFooter>
                          <AlertDialogCancel className="border-[#333] bg-transparent text-white hover:bg-[#333]">
                            Cancel
                          </AlertDialogCancel>
                          <AlertDialogAction
                            onClick={() => handleDelete(user.id, user.name)}
                            className="bg-red-600 text-white hover:bg-red-700"
                          >
                            Delete
                          </AlertDialogAction>
                        </AlertDialogFooter>
                      </AlertDialogContent>
                    </AlertDialog>
                  ) : null}
                </div>
              </div>
            ))}
          </div>
        )}

        {!loading && users.length === 0 && (
          <div className="flex flex-col items-center justify-center rounded-lg border border-[#333] bg-[#222] py-12">
            <UserCircle className="mb-4 h-12 w-12 text-gray-600" />
            <p className="text-lg font-medium text-gray-400">No users found</p>
            <p className="text-sm text-gray-500">
              Try adjusting your search or add a new user
            </p>
          </div>
        )}

        {!loading && pagination && pagination.totalPages > 1 && (
          <div className="mt-6 flex items-center justify-between">
            <Button
              variant="outline"
              disabled={!pagination.hasPrevPage}
              onClick={() => setPage((p) => Math.max(1, p - 1))}
              className="border-[#333] bg-transparent text-white hover:bg-[#333]"
            >
              Previous
            </Button>

            <p className="text-sm text-gray-400">
              Page {page} of {pagination.totalPages}
            </p>

            <Button
              variant="outline"
              disabled={!pagination.hasNextPage}
              onClick={() => setPage((p) => p + 1)}
              className="border-[#333] bg-transparent text-white hover:bg-[#333]"
            >
              Next
            </Button>
          </div>
        )}
      </div>
    </div>
  );
}
